import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    bids = {}  # price in cents -> resting quantity
    asks = {}
    out = []

    def fmt(c):
        return f"{c // 100}.{c % 100:02d}"

    idx = 1
    for _ in range(n):
        typ = data[idx].decode(); side = data[idx + 1].decode()
        price = int(data[idx + 2]); qty = int(data[idx + 3])
        idx += 4
        book = bids if side == "B" else asks
        book[price] = book.get(price, 0) + (qty if typ == "A" else -qty)
        if book[price] == 0:
            del book[price]
        bb = max(bids) if bids else None
        ba = min(asks) if asks else None
        if bb is None and ba is None:
            out.append("- - -")
        elif ba is None:
            out.append(f"{fmt(bb)} - -")
        elif bb is None:
            out.append(f"- {fmt(ba)} -")
        else:
            out.append(f"{fmt(bb)} {fmt(ba)} {fmt(ba - bb)}")
    sys.stdout.write("\n".join(out) + "\n")

main()

