#include <bits/stdc++.h>
using namespace std;

static string fmt(long long c) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%lld.%02lld", c / 100, c % 100);
    return string(buf);
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    map<long long, long long, greater<long long>> bids; // begin() = best (highest) bid
    map<long long, long long> asks;                     // begin() = best (lowest) ask
    string out;
    for (int i = 0; i < n; i++) {
        char t[4], s[4];
        long long price, qty;
        scanf("%3s %3s %lld %lld", t, s, &price, &qty);
        if (s[0] == 'B') {
            if (t[0] == 'A') bids[price] += qty;
            else { bids[price] -= qty; if (bids[price] == 0) bids.erase(price); }
        } else {
            if (t[0] == 'A') asks[price] += qty;
            else { asks[price] -= qty; if (asks[price] == 0) asks.erase(price); }
        }
        bool hb = !bids.empty(), ha = !asks.empty();
        out += hb ? fmt(bids.begin()->first) : "-";
        out += " ";
        out += ha ? fmt(asks.begin()->first) : "-";
        out += " ";
        out += (hb && ha) ? fmt(asks.begin()->first - bids.begin()->first) : "-";
        out += "\n";
    }
    fputs(out.c_str(), stdout);
    return 0;
}
